 error(e){if(e.message==='CO_DISPATCH_MONTH_MISMATCH')return this.t('派车月份已变更，请按销售计划刷新','Refresh to use the sales plan shipment month');if(e.message==='CO_LOADING_ARRIVAL_FROZEN')return this.t('车辆已创建装车计划，请在装车计划中处理','This vehicle has a loading plan. Open the plan to continue');const x={CO_SALES_INPUT:['输入字段无效','Invalid input fields'],CO_SALES_NOT_FOUND:['记录不存在或不在授权范围','Record not found or outside your scope'],CO_SALES_STALE:['记录已变化，请保留输入并刷新核对','Record changed. Keep your input and refresh to verify'],CO_SALES_IDENTITY:['产品、客户、合同、仓库和车牌身份不可更改','Product, customer, contract, warehouse and truck identity cannot change'],CO_SALES_LOCKED:['销售计划已关闭或车辆已取消','Sales plan is closed or vehicle is cancelled'],CO_SALES_CONFLICT:['合同、车牌、关联记录或状态冲突，请核对后重试','Contract, truck identity, linked record or state conflict. Verify and retry'],CO_SALES_PREVIEW:['文件变化或尚未确认识别列，请重新预览','File changed or columns are unconfirmed. Preview again'],CO_SALES_MONTH:['请选择有效发运月份','Select a valid shipment month'],CO_SALES_COUNT:['计划车辆数量必须为正整数','Planned vehicle count must be a positive integer'],CO_SALES_CONTRACT_DATE:['合同截止日期不能早于生效日期','Contract end date cannot precede its effective date'],CO_SALES_SCOPE:['项目或仓库不在授权范围','Project or warehouse is outside your scope']};if(/^CO_SALES_.*无效$/.test(e.message))return this.t('请填写有效的必填信息','Enter valid required information');return x[e.message]?this.t(...x[e.message]):CobaltUI.error(e);},
