 table(headings,rows,id){return `<div class="business-table"><table id="${id}"><thead><tr>${headings.map(([z,e])=>'<th>'+this.t(z,e)+'</th>').join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headings.length}">${this.t('暂无记录','No Records')}</td></tr>`}</tbody></table></div>`;},
