 async planForm(id,saved){const o=await API.request(this.base+'/options'),p=saved||(id?await API.request(this.base+'/plans/'+id):{}),edit=!!id,write=this.can('plan:write');this.data=p;this.page(this.t(edit?'销售计划详情':'新增氢氧化钴销售计划',edit?'Sales Plan Details':'Create Cobalt Sales Plan'),`<h2>${esc(p.code||'')}</h2><p>${this.t('客户和合同在销售计划阶段确定。预计金属吨与备货实际ARECOMS独立，不改变批次金属量。','Customer and contract are assigned at the sales plan stage. Planned metal MT is independent of actual batch ARECOMS and never changes it.')}</p><form id="co-sales-plan-form" class="user-form"><fieldset ${write?'':'disabled'}><div class="form-grid"><label>${this.t('项目','Project')}<select name="project_id" ${edit?'disabled':''} required>${o.projects.map(x=>`<option value="${x.id}" ${x.id===p.project_id?'selected':''}>${esc(I18n.translate(x.name,true))}</option>`).join('')}</select></label><label>${this.t('仓库','Warehouse')}<select name="warehouse_id" ${edit?'disabled':''} required></select></label><label>${this.t('客户','Customer')}<select name="customer_id" ${edit?'disabled':''} required></select></label><label>${this.t('钴销售合同','Cobalt Sales Contract')}<select name="contract_id" ${edit?'disabled':''} required></select></label>${this.field('shipment_month','计划发运月份','Shipment Month',p.shipment_month,'month')}${this.field('target_weight','计划发运数量（吨）','Planned Shipment Quantity (MT)',p.target_weight)}${this.field('planned_metal_mt','计划发运ARECOMS钴金属吨数（预计）','Planned ARECOMS Metal MT (Estimate)',p.planned_metal_mt,'text',false)}${this.field('planned_vehicle_count','计划车辆数量','Planned Vehicles',p.planned_vehicle_count,'number')}${this.field('destination','目的地','Destination',p.destination)}<label>${this.t('状态','Status')}<select name="status">${['OPEN','CLOSED'].map(s=>`<option value="${s}" ${s===p.status?'selected':''} ${!edit&&s==='CLOSED'?'disabled':''}>${this.state(s)}</option>`).join('')}</select></label></div><label>${this.t('备注','Remarks')}<textarea name="remark" maxlength="1000">${esc(p.remark||'')}</textarea></label><p id="co-sales-error" class="error" role="alert"></p>${write?`<button id="co-sales-save" class="button primary">${this.t('保存销售计划','Save Sales Plan')}</button>`:''}</fieldset></form>${edit?`<div class="business-toolbar">${this.can('dispatch:read')?`<a class="button secondary" href="/sales-plans/${id}/dispatch">${this.t('派车管理','Dispatch Management')}</a>`:''}<span>${this.t('创建人 / 时间','Creator / Time')}: ${esc(I18n.language==='en'?(p.creator_name_en||p.creator_name):p.creator_name)} · ${esc(p.created_at)}</span></div><section id="co-sales-history"></section>`:''}`);const f=$('co-sales-plan-form'),contracts=()=>{f.elements.contract_id.innerHTML='<option value="">'+this.t('请选择钴合同','Select Cobalt Contract')+'</option>'+o.contracts.filter(x=>x.project_id===f.elements.project_id.value&&x.customer_id===f.elements.customer_id.value&&(x.active||x.id===p.contract_id)).map(x=>`<option value="${x.id}" ${x.id===p.contract_id?'selected':''}>${esc(x.contract_no)}</option>`).join('');},project=()=>{const id=f.elements.project_id.value;f.elements.warehouse_id.innerHTML=o.warehouses.filter(x=>x.project_id===id).map(x=>`<option value="${x.id}" ${x.id===p.warehouse_id?'selected':''}>${esc(I18n.translate(x.name,true))}</option>`).join('');f.elements.customer_id.innerHTML='<option value="">'+this.t('请选择客户','Select Customer')+'</option>'+o.customers.filter(x=>x.project_id===id&&(x.active||x.id===p.customer_id)).map(x=>`<option value="${x.id}" ${x.id===p.customer_id?'selected':''}>${esc(x.name)}</option>`).join('');contracts();};project();f.elements.project_id.onchange=project;f.elements.customer_id.onchange=contracts;f.onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const b=this.values(f);b.planned_vehicle_count=Number(b.planned_vehicle_count);if(edit)b.version=p.version;const r=await API.request(this.base+'/plans'+(edit?'/'+id:''),{method:'POST',body:b});ProductContext.dirty=false;await Router.go('/sales-plans/'+r.id);}catch(e){$('co-sales-error').textContent=this.error(e);}finally{if(e.submitter.isConnected)e.submitter.disabled=false;}};if(edit)await this.history(id);ProductContext.dirty=false;},
